import { renderToStaticMarkup } from "react-dom/server";
import { describe, expect, it } from "vitest";
import { CallSummary } from "../../components/sections/CallSummary";
import type { EndCallResult } from "../api";
// Real output from the backend's /end route (generated by its test harness), not hand-written.
import backendRecord from "./fixtures/backend-end-call.json";

const record = backendRecord as unknown as EndCallResult;
const decode = (html: string) => html.replace(/&quot;/g, '"').replace(/&#x27;/g, "'").replace(/&amp;/g, "&");

describe("CallSummary panel", () => {
  it("shows an empty state before any call, with no sample data", () => {
    const html = renderToStaticMarkup(<CallSummary localTranscript={[]} record={null} recordError={null} saving={false} />);
    expect(html).toContain("No calls yet");
    expect(html).not.toContain("ORD-");
  });

  it("renders the saved transcript in order with speaker labels", () => {
    const html = decode(renderToStaticMarkup(<CallSummary localTranscript={[]} record={record} recordError={null} saving={false} />));
    const lines = record.transcript.map((t) => t.text);
    const positions = lines.map((line) => html.indexOf(line));
    expect(positions.every((p) => p > 0)).toBe(true);
    expect([...positions].sort((a, b) => a - b)).toEqual(positions);
    expect(html).toContain(">Aria<");
    expect(html).toContain(">Customer<");
  });

  it("shows the key outcome fields and the full JSON summary", () => {
    const html = decode(renderToStaticMarkup(<CallSummary localTranscript={[]} record={record} recordError={null} saving={false} />));
    expect(html).toContain("Order tracking");
    expect(html).toContain("ORD-101");
    expect(html).toContain("Resolved");
    const pre = html.slice(html.indexOf("<pre"), html.indexOf("</pre>"));
    const json = JSON.parse(pre.slice(pre.indexOf(">") + 1));
    expect(json).toEqual(record.summary);
  });

  it("shows a saving state, then an honest error with the unsaved transcript if saving failed", () => {
    expect(renderToStaticMarkup(<CallSummary localTranscript={[]} record={null} recordError={null} saving />)).toContain(
      "Saving the call record",
    );
    const html = decode(
      renderToStaticMarkup(
        <CallSummary
          localTranscript={[{ id: "t0", speaker: "customer", text: "Where is ORD-101?", at: 0, final: true }]}
          record={null}
          recordError="The call ended, but its summary couldn't be saved. The transcript below was not saved."
          saving={false}
        />,
      ),
    );
    expect(html).toContain('role="alert"');
    expect(html).toContain("Where is ORD-101?");
    expect(html).not.toContain("<pre");
  });
});
